package com.codegym.inotes.controller;
import com.codegym.inotes.model.Note; import com.codegym.inotes.service.NoteManagement; import com.codegym.inotes.strategy.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.util.*;
@WebServlet("/notes") public class NoteServlet extends HttpServlet { private NoteManagement management; public void init(){String storage=getServletConfig().getInitParameter("storage");management=new NoteManagement("file".equalsIgnoreCase(storage)?new NoteFileStrategy(getServletContext().getRealPath("/WEB-INF/notes.txt")):new NoteDBStrategy("jdbc:mysql://localhost:3306/inotes_db?useSSL=false&serverTimezone=UTC","root",""));} protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String a=r.getParameter("action");if("delete".equals(a)){management.deleteNote(Integer.parseInt(r.getParameter("id")));s.sendRedirect("notes");return;}r.setAttribute("notes",management.searchNotes(r.getParameter("keyword")));r.getRequestDispatcher("/WEB-INF/views/notes.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{management.addNote(r.getParameter("title"),r.getParameter("content"),Integer.parseInt(r.getParameter("typeId")));s.sendRedirect("notes");}catch(Exception e){throw new ServletException(e);}} }
